corrected_code:
io.on('connection', (socket) => {
  socket.on('telemetry:set_threshold', async ({ facilityId, sensorId, maxPsiThreshold }) => {
    const engineer = await FacilityStaff.findOne({ userId: socket.data.userId, facilityId, role: 'CHIEF_ENGINEER' });
    if (!engineer) {
      return socket.emit('error', { message: 'Unauthorized: insufficient facility engineering clearances' });
    }
    await SensorConfig.updateOne({ facilityId, sensorId }, { maxPressurePsi: maxPsiThreshold });
    io.to(`facility:${facilityId}`).emit('threshold_recalibrated', { sensorId, maxPsiThreshold });
  });
});
